// Redraws of icons marked Needs work in the 2026-11-15 review (redraw round 2).
// The old recipes were in canned-coffee-refreshments-13.mjs (stok-cold-brew-not-too-sweet,
// chameleon-cold-brew-black, kitu-super-coffee-mocha, bulletproof-coffee-rtd-vanilla) and
// starter-smoothies.mjs (stok-cold-brew-black).
//
// The brand marks and label lettering held in the path constants below were vectorised from
// the packshots recorded in each record: cropped, thresholded on the ink colour and fitted
// with cubic Beziers. They keep the photo's own cylinder foreshortening, so the lettering
// bends with the bottle. Plain bold-sans descriptors are Arial.
import {wrap, shadow, ref, text} from '../style.mjs';

const date = '2026-11-15';
const r2 = v => Math.round(v * 100) / 100;
const evidence = (pageUrl, imageUrl, observations) => ({pageUrl, imageUrl, inspectedAt: date, visuallyInspected: true, observations});
const record = (slug, family, packageChoice, references, uncertainty, svg) => ({slug, family, packageChoice, references, uncertainty, status: 'needs-review', svg});

