// ---------------------------------------------------------------------------------------------
// Bulletproof Vanilla Cold Brew Latte, 8 fl oz slim can: the canned line that replaced the
// 11.1 fl oz cartons in 2020 and the most recent ready-to-drink vanilla package documented.
// Can body, lid and rim follow the Good slim-can helper (energy-variants.mjs) so it sits with
// the other 250 mL-class cans. The vertical BULLETPROOF wordmark and COLD BREW LATTE are
// vectorised from the retailer packshot; the can is shown as that packshot shows it, turned so
// the orange band sits left of centre and the claims column right.
function bulletproofVanilla() {
  const l = 60, r = 140, t = 24, rx = 34;
  const body = `M${l + 6} ${t}Q100 ${t - 8} ${r - 6} ${t}L${r} ${t + 16}V220Q${r} 233 100 233T${l} 220V${t + 16}Z`;
  const orange = '#f55a14', blue = '#1494d2';
  const lt = (x, y, label, size, fill, attrs = '') => `<text x="${x}" y="${y}" font-family="Arial,sans-serif" font-size="${size}" fill="${fill}" ${attrs}>${label}</text>`;
  const label = `<path d="M102 33.5L108.9 45.8M114.3 25L123.6 46.8M128.9 64.8L134.8 93.8M127.6 92L132.9 115M66 64.8L69.5 72.5M64.1 87.9L69.5 93.8M102.8 139.9L140.1 176.6M119.6 141.7L140.1 166.4M127.3 134L138.3 158.7M130.3 122L137.5 143.3M63.6 118L68.6 127" fill="none" stroke="#e3cf8a" stroke-width=".35"/>
<path d="M71.6 10H99.3V154H71.6Z" fill="${ref('band')}"/>
<path d="${BP_WORDMARK}" fill="#fffdfa" fill-rule="evenodd"/>
<path d="M104.7 49.7H126.3V69.4H104.7Z" fill="none" stroke="${orange}" stroke-width=".4"/>
${text(115.5, 60.2, 'KETO', 6.7, orange, 'font-weight="bold" textLength="15.6" lengthAdjust="spacingAndGlyphs"')}
${text(115.5, 65.9, 'FRIENDLY', 3.2, orange, 'font-weight="bold" textLength="16" lengthAdjust="spacing"')}
${text(115.5, 79.9, '8g', 9, orange, 'font-weight="bold" textLength="9.6" lengthAdjust="spacingAndGlyphs"')}
${text(115.5, 87.4, 'COLLAGEN', 3.9, orange, 'font-weight="bold" textLength="22" lengthAdjust="spacing"')}
${text(115.5, 92.9, 'PROTEIN', 3.9, orange, 'font-weight="bold" textLength="17.6" lengthAdjust="spacing"')}
<path d="M104.7 97.1H126.3M104.7 119.2H126.3" fill="none" stroke="${orange}" stroke-width=".35"/>
<path d="M116.4 101C114.8 103.6 113.5 105.2 113.5 106.9C113.5 108.5 114.8 109.7 116.4 109.7C118 109.7 119.3 108.5 119.3 106.9C119.3 105.2 118 103.6 116.4 101ZM116.4 105.4V108M115.1 106.7H117.7" fill="none" stroke="${orange}" stroke-width=".4" stroke-linejoin="round"/>
${text(115.5, 115.1, 'MCT OIL', 3.9, orange, 'font-weight="bold" textLength="16.8" lengthAdjust="spacing"')}
${text(115.5, 131, '0g', 9, orange, 'font-weight="bold" textLength="9.6" lengthAdjust="spacingAndGlyphs"')}
${text(115.5, 137, 'SUGAR', 3.9, orange, 'font-weight="bold" textLength="14.6" lengthAdjust="spacing"')}
<g clip-path="${ref('blueclip')}"><path d="M56 150H144V240H56Z" fill="${blue}"/>
<path d="M56 186C70 176 82 190 96 180C110 170 120 176 144 164V176C124 186 112 180 98 190C84 200 70 188 56 198Z" fill="#35c1ea" opacity=".55"/>
<path d="M56 208C74 196 86 214 104 202C118 193 130 200 144 190V200C130 210 118 203 106 212C88 224 72 208 56 220Z" fill="#4fcdf0" opacity=".45"/>
<path d="M62 232C76 218 92 232 106 222C120 212 132 220 144 212V224C130 232 120 226 108 234C94 242 78 230 62 240Z" fill="#0d74b8" opacity=".45"/>
<path d="M86 170C96 162 108 168 118 162C126 158 134 166 144 160" fill="none" stroke="#5fd3f2" stroke-opacity=".5" stroke-width="2.2" stroke-linecap="round"/>
<path d="M58 178C66 170 74 174 82 168" fill="none" stroke="#1578b2" stroke-opacity=".35" stroke-width="2.6" stroke-linecap="round"/>
<path d="M112 196C120 190 130 196 142 186" fill="none" stroke="#1578b2" stroke-opacity=".3" stroke-width="3" stroke-linecap="round"/></g>
<path d="${BP_PRODUCT}" fill="#fffdfa" fill-rule="evenodd"/>
${lt(71.6, 198.9, 'COFFEE BEVERAGE', 3.5, '#fffdfa', 'font-weight="bold" textLength="30.6" lengthAdjust="spacingAndGlyphs"')}
${lt(71.6, 203.6, 'WITH GRASS-FED BUTTER', 3.5, '#fffdfa', 'font-weight="bold" textLength="43.4" lengthAdjust="spacingAndGlyphs"')}
${lt(71.4, 217, 'Vanilla', 6.2, '#fffdfa', 'font-weight="bold" textLength="17.2" lengthAdjust="spacingAndGlyphs"')}
${lt(71.6, 221.4, 'Flavored with other natural flavors', 2.3, '#fffdfa', 'textLength="32.6" lengthAdjust="spacingAndGlyphs"')}`;
  return wrap('bulletproof-coffee-rtd-vanilla', 'Bulletproof Vanilla Cold Brew Latte', `${shadow(49)}<path d="${body}" fill="#f8f7f4"/>
<g clip-path="${ref('bodyclip')}">${label}<path d="${body}" fill="${ref('shade')}" opacity=".8"/>
<path d="M${l + 8} ${t + 22}V214" fill="none" stroke="#fff" stroke-opacity=".2" stroke-width="2.8"/></g>
<ellipse cx="100" cy="${t}" rx="${rx}" ry="7" fill="${ref('metal')}" stroke="#9ca7a4" stroke-width="1.1"/>
<ellipse cx="100" cy="${t}" rx="${rx - 4}" ry="4.6" fill="none" stroke="#8d9892" stroke-width=".7"/>
<ellipse cx="104" cy="${t + 1}" rx="7" ry="2.8" fill="#657169"/>
<path d="M94 ${t - 2}h9q5 0 4 3t-7 3h-5q-5-1-1-6" fill="none" stroke="#e6e8de" stroke-width="2.2"/>
<path d="M${l + 3} 226q${(r - l - 6) / 2} 12 ${r - l - 6} 0" fill="none" stroke="${ref('metal')}" stroke-width="4"/>
<path d="M${l + 6} 230q${(r - l - 12) / 2} 7 ${r - l - 12} 0" fill="none" stroke="#fff" stroke-opacity=".5" stroke-width="1"/>`,
  `<clipPath id="__ID__bodyclip"><path d="${body}"/></clipPath>
<clipPath id="__ID__blueclip"><path d="M56 175.6L116.1 159.7L144 178.4V240H56Z"/></clipPath>
<linearGradient id="__ID__band" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#ee4f0c"/><stop offset=".5" stop-color="#fb6417"/><stop offset="1" stop-color="#f25710"/></linearGradient>`);
}

